    OUT(8) = TMR_CNT(0);
    TMR_CON(0) = 1u | (2u << 4) | 0x4000u;
    OUT(9) = TMR_CNT(0);
    record(t, TMR_CNT(4), 6u);
    if (OUT(1) == 2u) {
        TMR_CON(0) = 0x4000u;
        OUT(0) = 0x600dd00eu;
    }
}

