#!/bin/sh
# SPDX-License-Identifier: MIT
# SPDX-FileCopyrightText: 2026 japes98
#
# C-SPEC-EXPERIMENTS: rebuilds the spec-side experiments and checks they
# match the committed images, then runs experiments.suite against this
# checkout's fwtest (harness/ci.sh's image, built if missing) in a fresh
# container with no network. Every case must have its expected outcome and
# match its golden files: the results docs/HARDWARE-SPEC.md cites.
#
#   harness/spec-experiments/run.sh OUT
set -eu

HERE=$(cd "$(dirname "$0")" && pwd)
ROOT=$(cd "$HERE/../.." && pwd)
out=${1:?usage: run.sh OUT}

sh "$HERE/build.sh" --check
t=$(sh "$ROOT/harness/ci.sh" tag)
docker image inspect "$t" >/dev/null 2>&1 || sh "$ROOT/harness/ci.sh" image >/dev/null
rm -rf "$out"
mkdir -p "$out"
out=$(cd "$out" && pwd)
docker run --rm --platform linux/amd64 --network none --user "$(id -u):$(id -g)" \
    -v "$HERE:/experiments:ro" -v "$out:/out" "$t" \
    suite /experiments/experiments.suite --out /out/suite
echo "spec experiments: every case matched its golden files"
    }

    #[inline]
    pub fn next_tick_due(&self) -> bool {
        self.cycles + 1 >= self.next_due
    }

    /// Any interrupt source pending at all (before enables and priorities).
    #[inline(always)]
    pub fn any_pending(&self) -> bool {
        self.t5_pending || self.alnk_pend & 0xf0 != 0 || self.ilat != 0 || self.tick_pending || self.spi1_pending
            || self.tmr.iter().any(|t| t.pending) || self.adc_irq || self.spi2_pending || self.uart_irq
    }

    /// The highest-priority source cpu0 has enabled and that is pending: (irq, prio).
    pub fn pending_irq(&self) -> Option<(u8, u8)> {
        self.pending_irq_for(0)
    }

    /// The same for core `core` (its own enable bank).
    pub fn pending_irq_for(&self, core: u32) -> Option<(u8, u8)> {
        let bank = if core == 0 { &self.icfg } else { &self.icfg1 };
        let icfg = |n: u8| bank[(n >> 3) as usize];
        if !self.any_pending() {
            return None;
        }
        let mut best: Option<(u8, u8)> = None;
        let mut consider = |n: u8| {
            let nib = (icfg(n) >> ((n & 7) * 4)) & 0xf;
            if nib & 1 != 0 {
                let prio = ((nib >> 1) & 7) as u8;
                if best.map_or(true, |(_, p)| prio > p) {
                    best = Some((n, prio));
                }
            }
        };
        if self.t5_pending {
            consider(IRQ_TIMER5);
        }
        if self.tick_pending {
            consider(IRQ_OS_TICK);
        }
        if self.spi1_pending {
            consider(IRQ_SPI1);
        }
        if self.adc_irq {
            consider(IRQ_SARADC);
        }
        if self.spi2_pending {
            consider(IRQ_SPI2);
        }
        if self.uart_irq {
            consider(IRQ_UART1);
        }
        for i in 0..4 {
            if self.tmr[i].pending {
                consider(4 + i as u8);
            }
        }
        if self.alnk_pend & 0xf0 != 0 && self.alnk_con0 & 0x800 != 0 {
            consider(IRQ_ALNK0);

