     4	#include "asm/spi.h"
     5	
     6	/********************************************************************************************
     7	*当SPI需要接收不固定数据量时，系统打开不可屏蔽方式，详情example的不可屏蔽中断使用方法
     8	*1.首先系统打开不可屏蔽中断方式，SPI中断优先级设为7
     9	*2.中断函数定义在内部sram方式
    10	*3.中断函数用户自行处理
    11	*4.注意：使用不可屏蔽方式，接收区间，禁止对flash进行写操作，读操作只能非代码区（除非系统程序代码跑sdram模式）
    12	*********************************************************************************************/
    13	
    14	/******************************以下为例子****************************************************/
    15	#define JL_SPI          	JL_SPI2 //与spi设备对应：JL_SPI0 JL_SPI1 JL_SPI2
    16	#define RECV_SIZE_MAX   	1024 //先了解协议1帧的最大字节数在多少再配置该值，此次例子为1024
    17	#define RECV_SPI_HEAD_EN	1 // 1:接收数据有数据头部信息，0：每次接收的是固定数据量
    18	#define RECV_FPS        	3 //硬件缓冲帧切换使用，务必>=2帧
    19	
    20	#define SPI_BUF_USE_SRAM    1 //使用内部sram，静态
    21	
    22	#if SPI_BUF_USE_SRAM
    23	static volatile char recv_buf[RECV_SIZE_MAX * RECV_FPS] SEC_USED(.sram) ALIGNED(32);//spi硬件使用接收buf
    24	#else
    25	static volatile char *recv_buf = NULL;//spi硬件使用接收buf
    26	#endif
    27	static volatile int recv_buf_size = RECV_SIZE_MAX * RECV_FPS;//先了解协议最大字节数在多少再配置该值，此次例子为1024
    28	static volatile int recv_buf_offset = 0;
    29	static volatile char recv_read_cnt = 0;
    30	static volatile char recv_write_cnt = 0;
    31	
    32	static volatile char *app_recv_buf = NULL;//应用层使用的buf
    33	static volatile int app_recv_len = 0;
    34	static volatile char spi_head_ok = 0;
    35	
    36	#if RECV_SPI_HEAD_EN
    37	//比如按照协议，对方主机SPI协议为如下,头4字节为信息，读取size可知道连续数据有多少字节。
    38	//对方主机SPI协议发送为：先发4字节头信息，延时几个微秒就发送实际数据量，延时10几个毫秒，继续发送下一次数据，以此类推。
    39	//注意结构体需要1字节对齐
    40	
    41	#pragma pack(push)//保存对齐状态
    42	#pragma pack(1)//以 1 字节对齐
    43	struct spi_heads {
    44	    volatile u8 head;//固定 0xA5
    45	    volatile u8 resv;//预留字节
    46	    volatile u16 size;//接收字节长度，此处size<=65535（注意：SPI的DMA最大数据量为SPI_MAX_SIZE，当芯片为AC790N则SPI_MAX_SIZE = 65535，当芯片为AC791N则SPI_MAX_SIZE = 2^31
    47	};
    48	#pragma pack(pop)//恢复默认对齐状态
    49	
    50	static struct spi_heads *spi_head;
    51	#define SPI_HEAD_SIZE (sizeof(struct spi_heads))
    52	#else
    53	#define SPI_HEAD_SIZE	RECV_SIZE_MAX  //没有头部信息，则使用最大值的固定数据量
    54	#endif
    55	
    56	//定义中断回调函数，注意：中断函数不能调用系统API（调试期间可加打印printf函数），调用函数需要用户自写，调用其他API也需要指定到指定在内部sram，即sec(.volatile_ram_code)
    57	static ___interrupt void spi_irq_cb(void) sec(.volatile_ram_code) //中断函数，指定在内部sram
    58	{
    59	    JL_SPI->CON |= BIT(14);//清除中断标记
    60	    asm volatile("csync;");
    61	    if (recv_buf) {
    62	#if RECV_SPI_HEAD_EN
    63	        if (!spi_head_ok) { //没有接收头，就先解析头
    64	            spi_head = (struct spi_heads *)(recv_buf + recv_write_cnt * RECV_SIZE_MAX + recv_buf_offset);
    65	            if (spi_head->head == 0xA5) { //接收到头部，则接收剩下数据
    66	                recv_buf_offset += SPI_HEAD_SIZE;
    67	                JL_SPI->ADR = (u32)(recv_buf + recv_write_cnt * RECV_SIZE_MAX + recv_buf_offset);
    68	                JL_SPI->CNT = (u32)spi_head->size;//接收剩下字节
    69	                spi_head_ok = true;
    70	            } else { //头不对，继续接收头
    71	                JL_SPI->ADR = (u32)(recv_buf + recv_write_cnt * RECV_SIZE_MAX + recv_buf_offset);
    72	                JL_SPI->CNT = (u32)SPI_HEAD_SIZE;//继续接收数据头
    73	            }
    74	        } else
    75	#endif
    76	        {
    77	            //接收的是数据
    78	            spi_head_ok = false;
    79	            if (((recv_write_cnt + 1) == RECV_FPS && !recv_read_cnt) || (recv_read_cnt && (recv_write_cnt + 1) == recv_read_cnt)) {
    80	#if RECV_SPI_HEAD_EN
    81	                recv_buf_offset -= SPI_HEAD_SIZE;
    82	#else
    83	                recv_buf_offset = 0;
    84	#endif
    85	            } else {
    86	                recv_write_cnt = (++recv_write_cnt) >= RECV_FPS ? 0 : recv_write_cnt;
    87	                recv_buf_offset = 0;
    88	            }
    89	            JL_SPI->ADR = (u32)(recv_buf + recv_write_cnt * RECV_SIZE_MAX + recv_buf_offset);//偏移地址
    90	            JL_SPI->CNT = (u32)SPI_HEAD_SIZE;//继续接收数据头
    91	        }
    92	    }
    93	    asm volatile("csync;");
    94	}
    95	static void spi_test_task(void *p)
    96	{
    97	    void *spi_hdl = NULL;
    98	    int ret;
    99	
   100	    //1.打开spi设备
   101	    spi_hdl = dev_open("spi1", NULL);
   102	    if (!spi_hdl) {
   103	        printf("spi open err \n");
   104	        goto exit;
   105	    }
   106	    //2.注册中断函数
   107	    dev_ioctl(spi_hdl, IOCTL_SPI_SET_IRQ_FUNC, (u32)spi_irq_cb);
   108	#if !SPI_BUF_USE_SRAM
   109	    recv_buf = malloc(recv_buf_size);
   110	    if (!recv_buf) {
   111	        printf("err spi no buf \n");
   112	        goto exit;
   113	    }
   114	#endif // SPI_BUF_USE_SRAM
   115	    //3.配置接收模式，开启中断，开启SPI
   116	    JL_SPI->CON &= ~(BIT(10) | BIT(11) | BIT(2)); //1bit模式
   117	    JL_SPI->CON |= BIT(12);//接收模式
   118	    JL_SPI->CON |= BIT(13);//开启中断
   119	    JL_SPI->CON |= BIT(0);//开启SPI
   120	
   121	    recv_write_cnt = 0;
   122	    recv_read_cnt = 0;
   123	    recv_buf_offset = 0;
   124	    app_recv_buf = NULL;
   125	    //4.配置接收地址，如对方主机SPI协议为如下，注意：写JL_SPI->CNT之前需保证此时对方SPI还没有发送数据，否则中途接收数据会出错
   126	    JL_SPI->ADR = (u32)recv_buf;//配置硬件接收地址
   127	    //此处根据实际应用选择接收字节数，比如收到4字节数据头，在数据头解析后可知下次应该收多少字节
   128	    JL_SPI->CNT = (u32)SPI_HEAD_SIZE;//写该寄存器则正式启动硬件接收，例如此处先接收4字节，接收4字节完就进spi_irq_cb中断解析
   129	
   130	    while (1) {
   131	        //5.接收数据查询
   132	        //不可屏蔽中断方法，中断函数不能使用系统API，只能查询法
   133	        if (recv_read_cnt < recv_write_cnt || recv_read_cnt != recv_write_cnt) {
   134	#if RECV_SPI_HEAD_EN //接收包含有头部信息处理分支
   135	            struct spi_heads *spi_head = (struct spi_heads *)(recv_buf + recv_read_cnt * RECV_SIZE_MAX);
   136	            if (spi_head->head == 0xA5) { //接收到头部，则接收剩下数据
   137	                app_recv_buf = (char *)spi_head + SPI_HEAD_SIZE;
   138	                app_recv_len = spi_head->size;
   139	                //todo，数据处理
   140	                put_buf(app_recv_buf, app_recv_len);
   141	
   142	
   143	            }
   144	#else //接收没有头部信息处理分支
   145	            u8 *data = recv_buf + recv_write_cnt * RECV_SIZE_MAX;
   146	            //todo，数据处理
   147	            put_buf(data, RECV_SIZE_MAX);
   148	#endif
   149	            recv_read_cnt = (++recv_read_cnt) >= RECV_FPS ? 0 : recv_read_cnt;
   150	        }
   151	        os_time_dly(1);//延时1个tick，防止看门狗。不允许丢帧则注释这行：当注释掉这个行代码时，该任务优先级需要8以下（否则影响系统其他任务调度）。
   152	        //taskYIELD();//可以使用空闲时候调度任务一次
   153	    }
   154	
   155	exit:
   156	#if !SPI_BUF_USE_SRAM
   157	    if (recv_buf) { //释放内存
   158	        free(recv_buf);
   159	        recv_buf = NULL;
   160	    }
   161	#endif
   162	    if (spi_hdl) { //关闭spi设备
   163	        dev_close(spi_hdl);
   164	    }
   165	    while (1) { //等待其他任务杀此任务
   166	        os_time_dly(100);//延时100个tick，防止看门狗
   167	    }
   168	}
   169	
   170	static int c_main1(void)
   171	{
   172	    os_task_create(spi_test_task, NULL, 8, 1000, 0, "spi_test_task");
   173	    return 0;
   174	}
   175	late_initcall(c_main1);
