    pixel(240u * 240u - 1u, 0xffffu);
    cmd(0x11);
    cmd(0x3a); dat(0x55);
    cmd(0x29);
    cmd(0x2a); dat(0); dat(0); dat(0); dat(239);
    cmd(0x2b); dat(0); dat(0); dat(0); dat(239);
    cmd(0x2c);
    PC_OUT = 0x100;
    SPI1_ADR = (u32)FRAME;
    SPI1_CNT = BYTES;
    OUT(0) = 1u;
    return 0;
}
